-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_DISNEYLANDPARIS.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Paris'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_DISNEYLANDPARIS.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_DISNEYLANDPARIS.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: October SAP GL, ticketing, POS, PMS
SELECT SYSTEM$STREAM_HAS_DATA('SDP_DISNEYLANDPARIS.PUBLIC.STR_GL_JOURNAL') OR SYSTEM$STREAM_HAS_DATA('SDP_DISNEYLANDPARIS.PUBLIC.STR_TICKETING');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_DISNEYLANDPARIS.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-10';
-- step 3 · Fallback: reload night audits from the PMS API
CALL SDP_DISNEYLANDPARIS.SNOWBOTS.SP_RELOAD_FEED('HOTEL_PMS', '2026-10', source => 'PMS_API');
-- step 4 · Reconcile: ticketing, POS and PMS to SAP
CALL SDP_DISNEYLANDPARIS.SNOWBOTS.SP_RECONCILE(period => '2026-10', tolerance_pct => 0.5);
-- step 5 · Guardrail: completeness ≥ 98% and SAP difference = 0
SELECT MIN(completeness) >= 0.98 AND ABS(SUM(sap_diff)) = 0 FROM SDP_DISNEYLANDPARIS.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-10';
-- step 6 · Lock period 2026-10 (awaiting controller approval)
CALL SDP_DISNEYLANDPARIS.PUBLIC.SP_LOCK_PERIOD('2026-10', approved_by => :approver);

